answer = ifScript();

function ifScript() {
    let incomplete_tasks;
    let provisioning_plan = workflow.scratchpad.provisioning_plan;

    if (!provisioning_plan) {
        incomplete_tasks = 'no';
    } else {
        const current_task_index = provisioning_plan.findIndex((task) => task.type == current.stage && task.completed == false);
        if (current_task_index != -1) {
            workflow.info(`Setting provisioning task with id ${provisioning_plan[current_task_index].sys_id} as current task`);
            provisioning_plan[current_task_index].current_task = true;
            workflow.scratchpad.current_provisioning_task_id = provisioning_plan[current_task_index].sys_id;
            workflow.scratchpad.provisioning_plan = provisioning_plan;
            incomplete_tasks = 'yes';
        } else
            incomplete_tasks = 'no';
    }

    if (current.stage == 'before_provisioning' && incomplete_tasks == 'no') {
        current.stage = 'provisioning';
    } else if (current.stage == 'provisioning' && incomplete_tasks == 'no') {
        current.stage = 'sailpoint_provisioning';
    } else if (current.stage == 'sailpoint_provisioning' && incomplete_tasks == 'no') {
        current.stage = 'after_provisioning';
    } else if (current.stage == 'after_provisioning' && incomplete_tasks == 'no') {
        current.stage = 'provisioning_completed';
    }

    return incomplete_tasks;
}

