		"query":{
			"query": `id:${current.variables.identity_id}`
		}
	};
	const identity = new x_xal_idconnect.XalientUtilitiesCore().getPaginatedSearchResults(identity_search);
	const existing_access = identity[0].access.filter(access => access.id == current.variables.isc_access_item.sailpoint_id);

	if (existing_access.length > 0) {
		return 'yes';
	}
	return 'no';
}

