answer = ifScript();

function ifScript() {
    const item_config = new GlideRecord('x_xal_idconnect_catalog_item_config');
    item_config.addEncodedQuery(`catalog_item.sys_id=${current.cat_item.sys_id.toString()}`);
    item_config.query();

    if (item_config.next()) {
        if (//First condition - approval scheme is defined at the catalog item level and has an access item owner approval
			(item_config.approval_scheme == 'access_item_owner_only' || item_config.approval_scheme == 'manager_then_access_item_owner') || 
		
			//Second condition - Approval scheme is set to be defined at the access item level, which is defined, and has an access item owner approval
			(item_config.approval_scheme == 'use_access_item_scheme' && (current.variables.isc_access_item.approval_scheme == 'access_item_owner_only' || current.variables.isc_access_item.approval_scheme == 'manager_then_access_item_owner')) ||
			
			//Third Condition - Approval Scheme is set to be defined at the access item level, which is not defined, and the fallback scheme has an access item owner approval
			(item_config.approval_scheme == 'use_access_item_scheme' && (!current.variables.isc_access_item.approval_scheme || current.variables.isc_access_item.approval_scheme == '') &&
			(item_config.fallback_approval_scheme == 'access_item_owner_only' || item_config.fallback_approval_scheme == 'manager_then_access_item_owner'))) {
            
			return 'yes';
        }
        else
            return 'no';
    }
}

