workflow.scratchpad.provisioning_status_checks = 0;

let object_type;

switch (current.variables.isc_access_item.sailpoint_object_type.toString()) {
	case "role":
		object_type = "ROLE";
		break;
	case "accessprofile":
		object_type = "ACCESS_PROFILE";
		break;
	case "entitlement":
		object_type = "ENTITLEMENT";
		break;
}


const request_body = {
	"requestedFor": [current.variables.identity_id.toString()],
	"requestType": "GRANT_ACCESS",
	"requestedItems": [{
		"type": object_type,
		"id": current.variables.isc_access_item.sailpoint_id.toString(),
		"comment": current.variables.reason_for_request.toString()
	}]
};

try {
    workflow.info(`Submitting access request with body: \r\n\r\n${JSON.stringify(request_body)}`);

    const catalogItem = new x_xal_idconnect.XalientUtilitiesCatalogItem();
    const request_response = catalogItem.submitAccessRequest(request_body);

    const statusCode = request_response.getStatusCode();
    const rawBody = request_response.getBody();

    if (statusCode !== 202) {
        throw `Access request failed:
        Status Code: ${statusCode}
        Response Body: ${rawBody}`;
    }

    if (!rawBody) {
        throw "Access Request response body is null or empty.";
    }

    workflow.info(`Received access request response body: \r\n\r\n${rawBody}`);

    let response_body;
    try {
        response_body = JSON.parse(rawBody);
    } catch (parseError) {
        throw `Failed to parse response body: ${rawBody}`;
    }

    const access_request_ids = [];

    for (const request of response_body.newRequests) {
        for (const item of request.accessRequestIds) {
            access_request_ids.push(item);
        }
    }

    current.variables.access_request_ids = access_request_ids.toString();
    activity.result = 'success';

} catch (exception) {
    workflow.error(exception);
	workflow.scratchpad.provisioning_exception = exception;
    activity.result = 'processing_exception';
}

